import { IngestPipeline } from "@514labs/moose-lib";

// User Activity Event data model
export interface UserActivity {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number;
}

// Configure the ingest pipeline with optimized table ordering
// Primary query patterns:
// 1. Activity counts per user over a date range
// 2. Total duration per action type
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["user_id", "event_ts"] // Optimize for user-based time range queries
  },
  stream: true,
  ingestApi: true,
});

